#include "epaper_driver.h"
#include "GUI_Paint.h"

#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(epaper, LOG_LEVEL_DBG);

//static const size_t Imagesize = ((EPD_4in26_WIDTH % 8 == 0)? (EPD_4in26_WIDTH / 8 ): (EPD_4in26_WIDTH / 8 + 1)) * EPD_4in26_HEIGHT;
#define MAX_IMAGE_SIZE ((EPD_4in26_WIDTH/8u) * EPD_4in26_HEIGHT)
//Create a new image cache
static uint8_t DisplayImage[MAX_IMAGE_SIZE] = {0};

int epaper_init(void)
{
    LOG_DBG("ePaper Initialized");
    EPD_4in26_Init();
    ///EPD_4in26_Init_4GRAY();
    //EPD_4in26_Clear();
    Paint_NewImage(DisplayImage, EPD_4in26_WIDTH, EPD_4in26_HEIGHT, 0, WHITE);
    k_msleep(500);

    return 0;
}

int epaper_clear(void)
{
    LOG_DBG("Clear Screen");
    EPD_4in26_Clear();
}

void epaper_poweroff(void) 
{
    LOG_DBG("Power Off");
    EPD_4in26_Sleep();
}

/* NOTE: Init must already have been run prior to calling this API */
void epaper_re_poweron(void)
{
    LOG_DBG("re-Power On");
    EPD_4in26_RePowerOn();
}

void epaper_draw_bitmap(const unsigned char* bmp) {
    LOG_DBG("Draw bitmap image");
    Paint_SelectImage(DisplayImage);
    Paint_Clear(WHITE);
    Paint_DrawBitMap(bmp);
    EPD_4in26_Display(DisplayImage);
}

